import{S as c,o as d,c as r,a9 as n,B as i}from"./chunks/framework.DxG24V0C.js";const t="/agentsrc/images/codex/06-execution-pipeline.svg",l="/agentsrc/images/codex/06-cross-platform-sandbox.svg",u=JSON.parse('{"title":"Codex 沙箱引擎：如何把 AI 关进操作系统的笼子？","description":"","frontmatter":{"title":"Codex 沙箱引擎：如何把 AI 关进操作系统的笼子？"},"headers":[],"relativePath":"codex/06-sandboxing.md","filePath":"codex/06-sandboxing.md","lastUpdated":1788847143000}'),s={name:"codex/06-sandboxing.md"},m=Object.assign(s,{setup(p){const o=[{question:"在 Codex 中，当大模型生成了一条 shell_command 后，其真实的执行链路顺序是怎样的？",options:["底层执行 → Sandbox 封装 → 策略解析 → 执行审批","策略解析 → Sandbox 封装 → 底层执行 → 执行审批","策略解析 → 执行审批 → Sandbox 封装 → 底层执行","Sandbox 封装 → 执行审批 → 策略解析 → 底层执行"],correct:2,explanation:"真实的执行链路是：ExecPolicyManager 先解析策略，若需审批则发出请求（挂起等待用户）；通过后交由 SandboxManager 进行沙箱参数封装，最后启动子进程执行。"},{question:"在 Linux 平台上，Codex 目前实现文件系统隔离的主力防线机制是什么？",options:["使用 Docker 容器虚拟化技术，将每个工具执行放在独立的隔离容器中","使用 Linux 内核的 Landlock 特性，严格限制进程级的文件访问权限","使用 bubblewrap 挂载受限的文件系统视图，并辅以 seccomp 限制系统调用","使用 SELinux 或 AppArmor 安全模块，通过强制访问控制（MAC）进行拦截"],correct:2,explanation:"根据源码，Linux 环境下的沙箱默认使用 codex-linux-sandbox helper，主要依靠 bubblewrap 实现文件系统隔离，配合 seccomp 做系统调用限制，而 Landlock 是作为 fallback 保留的。"},{question:"ExecPolicy（指令策略引擎）在评估一条待执行的命令时，其判定结果包含哪三种状态？",options:["Success（成功）、Failure（失败）、Pending（等待）","Allow（允许）、Forbidden（禁止）、Prompt（要求人工审批）","Execute（执行）、Skip（跳过）、Retry（重试）","Safe（安全）、Warning（警告）、Danger（危险）"],correct:1,explanation:"在 execpolicy/src/decision.rs 中，策略引擎对命令的判定结果为 Allow、Forbidden 或 Prompt，进入 core 流程后转换为相应的 ExecApprovalRequirement。"},{question:"Codex 的 Process Hardening（进程加固）模块的主要职责是什么？",options:["在每次执行子进程前清洗 PATH 等环境变量，并重置工作目录（CWD）以防止逃逸","在主程序启动时进行全局自保，如禁用 Core Dump、禁止 ptrace attach，防止被调试或动态库劫持","动态生成 macOS 的 .sbpl 策略文件，拦截所有的网络访问请求","对模型生成的代码进行静态安全扫描，拦截潜在的 SQL 注入或恶意载荷"],correct:1,explanation:"process-hardening 主要在 Pre-main 阶段运行，用于保护代理主进程自身的内存与执行环境纯净。执行时的环境变量清洗和 CWD 重置则属于执行请求构造和沙箱的职责。"},{question:"从沙箱与安全机制的实现角度来看，采用 Rust 作为核心语言的工程优势之一是什么？",options:["Rust 的包管理器 Cargo 提供了比 npm 更严格的自动代码审计，防止了供应链攻击","Rust 的异步生成器（Async Generator）天然支持多 Agent 环境下的隔离并发执行","相比于 Node.js，Rust 更便于调用内核级沙箱 API 并精细控制子进程与系统资源","Rust 的编译速度远超 TypeScript，极大缩短了本地 Agent 系统的安装时间"],correct:2,explanation:"要实现深度的进程级沙箱隔离（如配置 bubblewrap 或 sandbox-exec 参数）以及系统级的自保护（禁用 ptrace 等），贴近操作系统的系统编程能力是 Rust 相比 TS 等语言的显著工程优势。"}];return(x,e)=>{const a=c("Quiz");return d(),r("div",null,[e[0]||(e[0]=n('<h1 id="codex-沙箱引擎-如何把-ai-关进操作系统的笼子" tabindex="-1">Codex 沙箱引擎：如何把 AI 关进操作系统的笼子？ <a class="header-anchor" href="#codex-沙箱引擎-如何把-ai-关进操作系统的笼子" aria-label="Permalink to &quot;Codex 沙箱引擎：如何把 AI 关进操作系统的笼子？&quot;">​</a></h1><p>想象你让 Agent “清理一下当前项目的临时文件”，但它因为幻觉或 Prompt 注入，生成了 <code>rm -rf ~/.ssh</code>。如果你用的是普通的 Node.js 代理，这行命令会直接在你的宿主机上以当前用户的权限执行。</p><p>当 Agent 具备了执行任意 Shell 命令的能力时，靠 System Prompt 里的软约束是防不住的。</p><p>Codex 的解法是：通过执行审批拦截高危命令，并通过跨平台的 OS 底层沙箱（如 Bubblewrap、Seatbelt）限制进程的文件与网络权限。本文将剥开 Codex 的外衣，深入探究这套安全架构在代码层面的真容，揭示沙箱策略落地的全过程：</p><ol><li>当模型尝试执行一个命令时，底层的真实执行链路是怎样的？</li><li><code>ExecPolicy</code> 引擎是如何通过规则树进行命令审批的？</li><li>Codex 是如何利用跨平台的 OS 机制实现进程级沙箱的？</li><li>进程加固（Process Hardening）的作用边界在哪里？</li></ol><p>本文只讨论底层的安全隔离与执行策略。关于多 Agent 之间如何隔离上下文，将留到下一篇《多 Agent 编排》中拆解。</p><h2 id="一、一条真实的执行链-命令是如何被拦截的" tabindex="-1">一、一条真实的执行链：命令是如何被拦截的？ <a class="header-anchor" href="#一、一条真实的执行链-命令是如何被拦截的" aria-label="Permalink to &quot;一、一条真实的执行链：命令是如何被拦截的？&quot;">​</a></h2><p>在 Codex 中，当大模型生成了一个 <code>shell_command</code> 或 <code>exec_command</code> 时，它并不是直接交给操作系统的 <code>exec</code>，而是会经历一条严密的管线：</p><p><img src="'+t+'" alt="命令执行的安全拦截管线"></p><ol><li><strong>策略解析</strong>：工具调用被交给 <code>ExecPolicyManager</code>。它会根据预设的规则树评估该命令，生成 <code>ExecApprovalRequirement</code>（允许、禁止、或需要审批）。</li><li><strong>执行审批</strong>：如果需要审批，核心引擎会向前端发出 <code>ExecApprovalRequest</code>，挂起任务等待用户决策（用户通过发送 <code>Op::ExecApproval</code> 消息回复）。</li><li><strong>沙箱封装</strong>：进入执行阶段前，请求会被交给 <code>SandboxManager::transform</code>。它会根据当前的 <code>PermissionProfile</code>（文件读写边界）和网络策略，将普通的命令转换为沙箱化的执行请求。</li><li><strong>底层执行</strong>：最后，带有沙箱包装的命令交由底层的 <code>exec server</code> 启动子进程。</li></ol><p>在这条链路上，文件系统权限、网络权限、命令审批和进程自保护被严格划分在不同的模块中。</p><h2 id="二、核心抽象-a-execpolicy-命令审批" tabindex="-1">二、核心抽象 A：ExecPolicy 命令审批 <a class="header-anchor" href="#二、核心抽象-a-execpolicy-命令审批" aria-label="Permalink to &quot;二、核心抽象 A：ExecPolicy 命令审批&quot;">​</a></h2><p>沙箱只能控制“能不能读写某个文件”，但控制不了“能不能执行某个命令”（比如 <code>git push</code>）。这就需要 <code>ExecPolicy</code>。</p><p>在 <code>codex-rs/execpolicy/src/</code> 中，系统实现了一个策略解析引擎。它会读取用户的策略配置（如“允许 <code>git *</code>，拒绝 <code>npm publish</code>，其他需审批”）。当引擎评估一条命令时，会返回三种判定结果（位于 <code>decision.rs</code>）：</p><ul><li><code>Allow</code>：静默放行。</li><li><code>Forbidden</code>：绝对禁止。</li><li><code>Prompt</code>：拦截并要求人工审批。</li></ul><p>进入核心流程后，这些决策会被转换为 <code>ExecApprovalRequirement::{Skip, Forbidden, NeedsApproval}</code>。这种设计让系统在静默自动化和高危人工兜底之间找到了平衡。</p><h2 id="三、核心抽象-b-跨平台-os-级沙箱" tabindex="-1">三、核心抽象 B：跨平台 OS 级沙箱 <a class="header-anchor" href="#三、核心抽象-b-跨平台-os-级沙箱" aria-label="Permalink to &quot;三、核心抽象 B：跨平台 OS 级沙箱&quot;">​</a></h2><p>当命令获准执行后，<code>SandboxManager</code> 开始介入。它将抽象的安全需求转化为操作系统的底层系统调用。</p><p><img src="'+l+'" alt="跨平台 OS 级沙箱机制"></p><h3 id="_3-1-linux-bubblewrap-与-seccomp" tabindex="-1">3.1 Linux：Bubblewrap 与 Seccomp <a class="header-anchor" href="#_3-1-linux-bubblewrap-与-seccomp" aria-label="Permalink to &quot;3.1 Linux：Bubblewrap 与 Seccomp&quot;">​</a></h3><p>在 Linux 平台上（位于 <code>codex-rs/linux-sandbox/</code>），目前的默认实现路径是：</p><ul><li><strong>文件系统隔离</strong>：使用 <code>bubblewrap</code>（一个轻量级的非特权沙箱工具）来挂载受限的文件系统视图，限制读写范围。</li><li><strong>网络与进程限制</strong>：辅以 <code>seccomp</code>（Secure Computing Mode）限制危险的系统调用。</li><li>（注：早期的 Landlock 实现作为 legacy/fallback 路径保留，不再是主力防线。）</li></ul><h3 id="_3-2-macos-seatbelt-策略" tabindex="-1">3.2 macOS：Seatbelt 策略 <a class="header-anchor" href="#_3-2-macos-seatbelt-策略" aria-label="Permalink to &quot;3.2 macOS：Seatbelt 策略&quot;">​</a></h3><p>在 macOS 平台上（位于 <code>codex-rs/sandboxing/src/seatbelt.rs</code>），系统利用了底层的 App Sandbox（又名 Seatbelt）机制。</p><p>Codex 会根据 <code>FileSystemSandboxPolicy</code> 和 <code>NetworkSandboxPolicy</code>，动态生成 <code>.sbpl</code> 格式的策略配置文件，然后强制命令通过 <code>/usr/bin/sandbox-exec -p &lt;policy&gt; &lt;cmd&gt;</code> 的形式启动。该策略不仅控制文件读写，还约束了 Unix Domain Socket、网络代理等高级权限。</p><p>（Windows 平台也有对应的 <code>WindowsRestrictedToken</code> 实现，本文从略。）</p><p>只要在受限的 Sandbox 生效状态下，即使大模型生成了 <code>rm -rf /</code>，操作系统内核也会在底层拒绝访问。</p><h2 id="四、核心抽象-c-进程自保护-process-hardening" tabindex="-1">四、核心抽象 C：进程自保护 (Process Hardening) <a class="header-anchor" href="#四、核心抽象-c-进程自保护-process-hardening" aria-label="Permalink to &quot;四、核心抽象 C：进程自保护 (Process Hardening)&quot;">​</a></h2><p>除了限制 Agent 执行的子进程，Codex 还会对自己（也就是代理主进程）进行保护。</p><p>在 <code>process-hardening/src/lib.rs</code> 中，定义了 Pre-main 的加固逻辑。它并不是每次执行命令时清洗环境变量（环境变量的处理发生在执行请求构造和沙箱阶段），而是在主程序刚启动时进行的全局自保：</p><ul><li>禁用 Core Dump。</li><li>禁止 <code>ptrace</code> attach（防止被其他进程调试并窃取内存中的 Token）。</li><li>移除危险的链接器变量（如 <code>LD_PRELOAD</code> 或 <code>DYLD_INSERT_LIBRARIES</code>），防止动态库劫持。</li></ul><p>这是典型的系统编程防御思路，用于保护 Codex 自身的运行环境纯净。</p><h2 id="五、关键决策-安全机制的工程实现优势" tabindex="-1">五、关键决策：安全机制的工程实现优势 <a class="header-anchor" href="#五、关键决策-安全机制的工程实现优势" aria-label="Permalink to &quot;五、关键决策：安全机制的工程实现优势&quot;">​</a></h2><p>把 Codex 的安全机制和基于 Node.js/TypeScript 构建的 Agent 对比，能看出实现路径上的差异。</p><p>相较于主要依赖权限确认（Prompt User）或纯逻辑拦截的工具形态，Codex 在开源实现里把 OS Sandbox 做成了执行链的一部分。</p><p>调用操作系统的沙箱机制（如管理 <code>bubblewrap</code> 或 <code>sandbox-exec</code> 的参数）、控制细粒度的子进程执行，并进行系统级的进程自保护，这些实现更贴近 Rust 的系统编程优势。这也是 Codex 在底层机制上显著区别于轻量级聊天代理的地方。</p><h2 id="六、总结" tabindex="-1">六、总结 <a class="header-anchor" href="#六、总结" aria-label="Permalink to &quot;六、总结&quot;">​</a></h2><p>Agent 的能力越强，其执行高危操作的风险就越大。</p><p>Codex 通过 ExecPolicy 进行命令审批拦截，通过跨平台的 OS 机制实现文件和网络隔离，最后用 Process Hardening 保护自身内存安全。这套严密的安全管线，让它可以更安全地在后台静默执行复杂的代码任务。</p><p>现在，我们的 Agent 已经有了大脑（主循环）、记忆（上下文）、手脚（工具）和铠甲（沙箱与策略）。但如果面对一个需要修改 50 个文件的史诗级重构任务，单兵作战还是会力不从心。下一篇，我们将看看 Codex 是如何通过 Agent Tree 组建“AI 团队”的。</p><h2 id="七、章节小测" tabindex="-1">七、章节小测 <a class="header-anchor" href="#七、章节小测" aria-label="Permalink to &quot;七、章节小测&quot;">​</a></h2>',41)),i(a,{questions:o})])}}});export{u as __pageData,m as default};
